import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query'; import { encountersApi } from '../api/encounters'; import type { CreateEncounterInput,UpdateEncounterInput } from '../types/models'; export function useCreateEncounter(id:string){const qc=useQueryClient();return useMutation({mutationFn:(p:CreateEncounterInput)=>encountersApi.create(id,p),onSuccess:e=>{void qc.invalidateQueries({queryKey:['appointments']});void qc.invalidateQueries({queryKey:['appointment',id]});void qc.invalidateQueries({queryKey:['records',e.patientId]})}})} export function useEncounter(id?:string){return useQuery({queryKey:['encounter',id],queryFn:()=>encountersApi.get(id!),enabled:Boolean(id)})} export function useUpdateEncounter(id:string){const qc=useQueryClient();return useMutation({mutationFn:(p:UpdateEncounterInput)=>encountersApi.update(id,p),onSuccess:e=>{void qc.invalidateQueries({queryKey:['encounter',id]});void qc.invalidateQueries({queryKey:['records',e.patientId]});void qc.invalidateQueries({queryKey:['appointment',e.appointmentId]})}})} export function usePatientRecords(pid?:string){return useQuery({queryKey:['records',pid],queryFn:()=>encountersApi.records(pid!),enabled:Boolean(pid)})}
